-- Keycloak's account e-mails, asked for through POST /hooks/keycloak by the e-mail hook provider
-- in the Keycloak image (ValueFarm.KeycloakTheme, providers/gpc-email-hook). While one of these is
-- off on the Transactional page, or cannot be sent, Keycloak sends its own e-mail instead.
-- Edit the wording in the dashboard; keep the keys. Merge tags: action_url (the link Keycloak
-- made: single use), expires_in ("12 hours"), expires_at, first_name, full_name, username,
-- realm_name, required_actions, company_address.
--
-- keycloak_execute_actions is the ValueFarm theme's bilingual credential-reset e-mail as it was
-- on 2026-11-23 (ValueFarm.KeycloakTheme docs/email-templates/executeActions.html).
INSERT INTO templates (id, key, name, category, mode, subject, html, is_standard) VALUES
('txn-keycloak-execute-actions', 'keycloak_execute_actions', 'ValueFarm: set a new password', 'transactional', 'html',
 'ValueFarm: reset your password ｜ ValueFarm：请重设你的密码',
$$<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"></head>
